import {objectEntries} from '@jetbrains/teamcity-ui/dist/utils'

import type {Property} from '../../../../services/rest'
import {ParameterGroup} from '../Parameters.types'

export function groupParameters(parameters: readonly Property[]) {
  return objectEntries(
    parameters.reduce<Record<ParameterGroup, Property[]>>(
      (acc, property) => {
        const name = property?.name

        if (name == null) {
          acc[ParameterGroup.CONFIGURATION].push(property)

          return acc
        }

        if (name.startsWith('system.')) {
          acc[ParameterGroup.SYSTEM].push(property)
        } else if (name.startsWith('env.')) {
          acc[ParameterGroup.ENVIRONMENT].push(property)
        } else if (name.startsWith('dep.')) {
          acc[ParameterGroup.DEPENDENCIES].push(property)
        } else {
          acc[ParameterGroup.CONFIGURATION].push(property)
        }
        return acc
      },
      {
        [ParameterGroup.CONFIGURATION]: [],
        [ParameterGroup.SYSTEM]: [],
        [ParameterGroup.ENVIRONMENT]: [],
        [ParameterGroup.DEPENDENCIES]: [],
      },
    ),
  ).map(([group, items]) => ({
    group,
    items,
  }))
}
