import {memo, useMemo} from 'react'
import type {EntryPointProps} from 'react-relay'
import {graphql, useFragment, usePreloadedQuery} from 'react-relay'

import ParametersGroupControls from '../../../../packages/Parameters/components/GroupControls/ParametersGroupControls'
import ParametersPageHeader from '../../../../packages/Parameters/components/PageHeader/ParametersPageHeader'
import {ParametersTree} from '../../../../packages/Parameters/components/ParametersTree/ParametersTree'
import ParametersSearch from '../../../../packages/Parameters/components/Search/ParametersSearch'
import {useSearchState} from '../../../../packages/Parameters/hooks/useSearchState'
import {ParameterCategory} from '../../../../packages/Parameters/Parameters.types'
import {useFilterSearch} from '../../../../packages/Parameters/utils/filterSearch'
import {groupParameters} from '../../../../packages/Parameters/utils/groupParameters'

import type {AgentParameters_agent$key} from './__generated__/AgentParameters_agent.graphql'
import type {AgentParametersQuery} from './__generated__/AgentParametersQuery.graphql'
import {query} from './AgentParameters.queries'

import styles from './AgentParameters.module.css'

import {inlineListMaxLength} from 'src/components/packages/Parameters/Parameters.consts'

const fragment = graphql`
  fragment AgentParameters_agent on AgentRest {
    properties {
      count
      ...filterSearch_parameters
    }
  }
`

interface Props {
  agentKey: AgentParameters_agent$key | null
}

function AgentParametersComponent(props: Props) {
  const {agentKey} = props
  const {properties = null} = useFragment(fragment, agentKey) ?? {}

  const {search, deferredSearch, handleChangeSearch, handleClearSearch} = useSearchState()

  const items = useFilterSearch({parametersKey: properties, search: deferredSearch})

  const parameters = useMemo(
    () => [
      {
        category: ParameterCategory.AGENT,
        groups: groupParameters(items).map(group => ({
          withDescription: true,
          header: {
            value: 'Value',
          },
          ...group,
        })),
      },
    ],
    [items],
  )

  const isVirtualized = (properties?.count ?? 0) > inlineListMaxLength

  return (
    <>
      <ParametersPageHeader>
        <ParametersSearch
          value={search}
          onChange={handleChangeSearch}
          onClear={handleClearSearch}
        />
        <ParametersGroupControls className={styles.controls} />
      </ParametersPageHeader>

      <ParametersTree highlight={search} parameters={parameters} isVirtualized={isVirtualized} />
    </>
  )
}

type Queries = {main: AgentParametersQuery}
const AgentParameters = memo(function AgentParameters({
  queries,
}: EntryPointProps<Queries, {}, {}, {}>) {
  const {agentRest = null} = usePreloadedQuery(query, queries.main) ?? {}
  return <AgentParametersComponent agentKey={agentRest} />
})
export default AgentParameters
export type AgentParametersComponentType = typeof AgentParameters
